return items.map(item => {
    const data = item.json.data;
    const impacted = item.json.impacted || "N/A";

    if (!data || !data.attributes) {
        return { json: { error: "No data found", impacted } };
    }

    const attrs = data.attributes;
    let stats = attrs.last_analysis_stats;

    // Build manually if needed
    if (!stats && attrs.last_analysis_results) {
        const engines = Object.values(attrs.last_analysis_results);
        stats = { malicious: 0, suspicious: 0, harmless: 0, undetected: 0 };
        for (const eng of engines) {
            const cat = eng.category || "undetected";
            if (stats[cat] !== undefined) stats[cat]++;
        }
    }

    const malicious = stats.malicious || 0;
    const suspicious = stats.suspicious || 0;
    const harmless = stats.harmless || 0;
    const undetected = stats.undetected || 0;
    const total = malicious + suspicious + harmless + undetected;
    const detectionRate = total > 0 ? ((malicious / total) * 100).toFixed(2) + "%" : "0%";

    const reputation = attrs.reputation || 0;
    const country = attrs.country || "Unknown";
    const asn = attrs.asn || 0;
    const status = malicious > 0 ? "MALICIOUS" : "CLEAN";
    const checkedAt = attrs.last_analysis_date
        ? new Date(attrs.last_analysis_date * 1000).toISOString()
        : new Date().toISOString();

    return {
        json: {
            Origin: data.id || "Unknown",
            Impacted: impacted,
            Malicious: malicious,
            Suspicious: suspicious,
            Harmless: harmless,
            Undetected: undetected,
            DetectionRate: detectionRate,
            Reputation: reputation,
            VT_Country: country,
            ASN: asn,
            Status: status,
            CheckedAt: checkedAt
        }
    };
});

