// Get raw email text
const text = items[0].json.text || "";

// Extract all IPv4 addresses
const ipRegex = /\b(?:\d{1,3}\.){3}\d{1,3}\b/g;
const allIPs = text.match(ipRegex) || [];

// Each row has 2 IPs in order: Origin first, Impacted second
// So we'll group them in pairs
const pairs = [];
for (let i = 0; i < allIPs.length; i += 2) {
  const origin = allIPs[i];
  const impacted = allIPs[i + 1];
  if (origin && impacted) {
    pairs.push({ origin, impacted });
  }
}

// Remove duplicates based on origin+impacted
const uniquePairs = Array.from(
  new Map(pairs.map(p => [p.origin + p.impacted, p])).values()
);

// Output each pair as a separate item for next node
return uniquePairs.map(p => ({ json: p }));

// Initialize Jira markdown table header
let jiraTable = "||Origin||Impacted||Malicious||Suspicious||Harmless||Undetected||DetectionRate||Reputation||Country||Status||\n";

// Loop through all items and populate rows
for (const item of items) {
    const origin = item.json.Origin || item.json.IP || "";
    const impacted = item.json.Impacted || "N/A";
    const malicious = item.json.Malicious || 0;
    const suspicious = item.json.Suspicious || 0;
    const harmless = item.json.Harmless || 0;
    const undetected = item.json.Undetected || 0;
    const detectionRate = item.json.DetectionRate || "0%";
    const reputation = item.json.Reputation || 0;
    const country = item.json.VT_Country || "";
    const status = item.json.Status || "";

    jiraTable += `|${origin}|${impacted}|${malicious}|${suspicious}|${harmless}|${undetected}|${detectionRate}|${reputation}|${country}|${status}|\n`;
}

// Return table string as JSON output
return [{ json: { jiraTable } }];

return items.filter(item => {
